INSERT INTO zodiac_signs (name, slug, date_start, date_end, element, planet, description) VALUES
('Овен', 'aries', '03-21', '04-19', 'Огонь', 'Марс', 'Энергичный, смелый и прямолинейный знак, который первым берётся за новое дело.'),
('Телец', 'taurus', '04-20', '05-20', 'Земля', 'Венера', 'Надёжный и терпеливый знак, ценящий комфорт, стабильность и красоту.'),
('Близнецы', 'gemini', '05-21', '06-20', 'Воздух', 'Меркурий', 'Любознательный и общительный знак, быстро схватывающий новую информацию.'),
('Рак', 'cancer', '06-21', '07-22', 'Вода', 'Луна', 'Чуткий и заботливый знак, для которого важны дом, семья и близкие люди.'),
('Лев', 'leo', '07-23', '08-22', 'Огонь', 'Солнце', 'Яркий и щедрый знак с врождёнными лидерскими качествами.'),
('Дева', 'virgo', '08-23', '09-22', 'Земля', 'Меркурий', 'Внимательный к деталям и практичный знак, стремящийся к порядку.'),
('Весы', 'libra', '09-23', '10-22', 'Воздух', 'Венера', 'Дипломатичный знак, ищущий гармонию, справедливость и равновесие.'),
('Скорпион', 'scorpio', '10-23', '11-21', 'Вода', 'Плутон', 'Страстный и проницательный знак с сильной волей и интуицией.'),
('Стрелец', 'sagittarius', '11-22', '12-21', 'Огонь', 'Юпитер', 'Оптимистичный знак, любящий путешествия, свободу и новые знания.'),
('Козерог', 'capricorn', '12-22', '01-19', 'Земля', 'Сатурн', 'Целеустремлённый и ответственный знак, уверенно идущий к вершине.'),
('Водолей', 'aquarius', '01-20', '02-18', 'Воздух', 'Уран', 'Независимый и изобретательный знак, опережающий своё время.'),
('Рыбы', 'pisces', '02-19', '03-20', 'Вода', 'Нептун', 'Мечтательный и сострадательный знак с богатым внутренним миром.');
