INSERT INTO astrologers (name, photo, specialization, experience, price, rating, about) VALUES
('Мира Звёздная', 'Mira.svg', 'Натальная карта', 12, 3500, 4.9, 'Профессиональный астролог, автор курсов по чтению натальной карты. Помогает понять сильные стороны личности и выбрать направление развития.'),
('Лев Орлов', 'Lev.svg', 'Синастрия и отношения', 9, 3000, 4.8, 'Специализируется на совместимости пар и анализе отношений. Консультирует по вопросам брака, партнёрства и семейной гармонии.'),
('Алиса Ветрова', 'Alisa.svg', 'Прогностика', 7, 2800, 4.7, 'Составляет прогнозы на год по транзитам и соляру. Помогает выбрать благоприятное время для важных решений.'),
('Герман Луч', 'German.svg', 'Карьера и финансы', 15, 4200, 4.9, 'Бизнес-астролог: подбор дат для открытия компании, анализ профессиональной реализации и финансового потенциала.'),
('Вера Полякова', 'Vera.svg', 'Натальная карта', 6, 2500, 4.6, 'Разбирает натальные карты простым языком, без пугающих прогнозов. Особое внимание уделяет Луне и эмоциональной сфере.'),
('Даниил Север', 'Daniil.svg', 'Таро и астрология', 8, 2200, 4.5, 'Сочетает астрологический анализ с раскладами Таро. Помогает в ситуациях выбора и сомнений.'),
('София Лунная', 'Sofia.svg', 'Синастрия и отношения', 10, 3300, 4.8, 'Работает с совместимостью и детско-родительскими отношениями. Проводит семейные консультации.'),
('Арсений Дальний', 'Arseny.svg', 'Прогностика', 11, 3600, 4.7, 'Специалист по ректификации времени рождения и долгосрочным прогнозам на основе прогрессий.');
