INSERT INTO horoscopes (sign_id, type_id, period, date_from, date_to, content, rating) VALUES
(1, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'День подходит для завершения старых дел и наведения порядка. Положение Луны советует действовать мягко и без давления. Вечер принесёт приятную встречу.', 4),
(1, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Венера благоприятствует романтическим свиданиям и признаниям. Марс поддерживает ваши начинания, поэтому смело делайте первый шаг. Лучшее время для важных дел — вечер.', 5),
(1, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'На работе появится шанс проявить себя перед руководством. Звёзды подсказывают: доверяйте опыту, а не слухам. Счастливое число дня — 28.', 3),
(1, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Хорошее время для начала полезной привычки. Марс поддерживает ваши начинания, поэтому смело делайте первый шаг. Лучшее время для важных дел — утро.', 3),
(1, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Удачный день для планирования бюджета на месяц. Сатурн напоминает о дисциплине и ответственности. Благоприятный цвет — серебристый.', 2),
(2, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Утро лучше посвятить планированию, а вечер — отдыху. Транзит Юпитера расширяет возможности — не упустите их. Счастливое число дня — 5.', 5),
(2, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Возможны мелкие разногласия, но их легко сгладить мягким словом. Сатурн напоминает о дисциплине и ответственности. Совет дня: записывайте идеи.', 3),
(2, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Хороший день для переговоров и подписания договоров. Звёзды подсказывают: доверяйте опыту, а не слухам. Счастливое число дня — 20.', 4),
(2, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Возможна лёгкая усталость к вечеру — снизьте нагрузку. Влияние стихии Земли делает вас особенно убедительными. Счастливое число дня — 33.', 3),
(2, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Не принимайте поспешных решений о вложениях. Сатурн напоминает о дисциплине и ответственности. Счастливое число дня — 5.', 5),
(3, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Сегодня важно не торопиться с выводами и выслушать окружающих. Влияние стихии Воздуха делает вас особенно убедительными. Счастливое число дня — 18.', 2),
(3, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Возможны мелкие разногласия, но их легко сгладить мягким словом. Аспект Меркурия облегчает общение и поиск компромиссов. Лучшее время для важных дел — вечер.', 4),
(3, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'На работе появится шанс проявить себя перед руководством. Марс добавляет решительности, но следите за эмоциями. Совет дня: берегите время.', 3),
(3, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Следите за режимом питания и пейте больше воды. Положение Луны советует действовать мягко и без давления. Благоприятный цвет — бирюзовый.', 3),
(3, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Не принимайте поспешных решений о вложениях. Сатурн напоминает о дисциплине и ответственности. Лучшее время для важных дел — после обеда.', 5),
(4, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'День подходит для завершения старых дел и наведения порядка. Сатурн напоминает о дисциплине и ответственности. Благоприятный цвет — золотой.', 3),
(4, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Возможны мелкие разногласия, но их легко сгладить мягким словом. Звёзды подсказывают: доверяйте опыту, а не слухам. Счастливое число дня — 32.', 2),
(4, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Хороший день для переговоров и подписания договоров. Сатурн напоминает о дисциплине и ответственности. Лучшее время для важных дел — утро.', 5),
(4, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Хорошее время для начала полезной привычки. Сатурн напоминает о дисциплине и ответственности. Вечер принесёт приятную встречу.', 5),
(4, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Финансовое положение стабильно, но от крупных трат лучше воздержаться. Звёзды подсказывают: доверяйте опыту, а не слухам. Счастливое число дня — 14.', 4),
(5, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'День начнётся спокойно, но к обеду события ускорятся. Влияние стихии Огня делает вас особенно убедительными. Счастливое число дня — 10.', 2),
(5, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Партнёр ждёт от вас искренности — не скрывайте чувств. Сатурн напоминает о дисциплине и ответственности. Благоприятный цвет — бордовый.', 5),
(5, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'На работе появится шанс проявить себя перед руководством. Влияние стихии Огня делает вас особенно убедительными. Вечер принесёт приятную встречу.', 2),
(5, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Подходящий день для прогулки на свежем воздухе и лёгкой зарядки. Влияние стихии Огня делает вас особенно убедительными. Совет дня: доверьтесь интуиции.', 2),
(5, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Возможна приятная премия или возврат долга. Транзит Юпитера расширяет возможности — не упустите их. Благоприятный цвет — серебристый.', 4),
(6, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'День подходит для завершения старых дел и наведения порядка. Положение Луны советует действовать мягко и без давления. Совет дня: доверьтесь интуиции.', 3),
(6, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Партнёр ждёт от вас искренности — не скрывайте чувств. Сатурн напоминает о дисциплине и ответственности. Благоприятный цвет — белый.', 2),
(6, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Коллеги охотно поддержат вашу инициативу. Марс добавляет решительности, но следите за эмоциями. Совет дня: берегите время.', 4),
(6, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Организм просит отдыха: ложитесь спать пораньше. Звёзды подсказывают: доверяйте опыту, а не слухам. Счастливое число дня — 15.', 3),
(6, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Не принимайте поспешных решений о вложениях. Меркурий поддерживает ваши начинания, поэтому смело делайте первый шаг. Вечер принесёт приятную встречу.', 5),
(7, 1, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Утро лучше посвятить планированию, а вечер — отдыху. Марс добавляет решительности, но следите за эмоциями. Благоприятный цвет — бордовый.', 5),
(7, 2, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Небольшой сюрприз для любимого человека укрепит связь. Влияние стихии Воздуха делает вас особенно убедительными. Благоприятный цвет — синий.', 5),
(7, 3, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Стоит обновить резюме или заняться обучением. Положение Луны советует действовать мягко и без давления. Лучшее время для важных дел — первая половина дня.', 2),
(7, 4, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Организм просит отдыха: ложитесь спать пораньше. Влияние стихии Воздуха делает вас особенно убедительными. Лучшее время для важных дел — первая половина дня.', 2),
(7, 5, 'day', DATE_ADD(CURDATE(), INTERVAL -1 DAY), DATE_ADD(CURDATE(), INTERVAL -1 DAY), 'Удачный день для планирования бюджета на месяц. Звёзды подсказывают: доверяйте опыту, а не слухам. Совет дня: начните с малого.', 4),
