INSERT INTO articles (title, slug, category, image, excerpt, content, astrologer_id, published_at, views) VALUES
('Ретроградный Меркурий: мифы и реальность', 'retrograde-mercury', 'Прогнозы', 'mercury.svg', 'Разбираемся, почему ретроградный Меркурий пугает многих и что на самом деле стоит учитывать в эти периоды.', 'Ретроградность — это видимое с Земли попятное движение планеты по небу. Физически Меркурий не меняет направление, но в астрологии этот период связывают с пересмотром планов, задержками и ошибками в коммуникации.
