-- База данных астрологического портала «Астерия»
-- СУБД: MySQL / MariaDB (XAMPP), кодировка utf8mb4

DROP DATABASE IF EXISTS asteria;
CREATE DATABASE asteria CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE asteria;

CREATE TABLE zodiac_signs (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(30) NOT NULL,
  slug VARCHAR(30) NOT NULL UNIQUE,
  date_start CHAR(5) NOT NULL,
  date_end CHAR(5) NOT NULL,
  element ENUM('Огонь','Земля','Воздух','Вода') NOT NULL,
  planet VARCHAR(30) NOT NULL,
  description TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE horoscope_types (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(30) NOT NULL,
  slug VARCHAR(30) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE horoscopes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  sign_id INT NOT NULL,
  type_id INT NOT NULL,
  period ENUM('day','week') NOT NULL DEFAULT 'day',
  date_from DATE NOT NULL,
  date_to DATE NOT NULL,
  content TEXT NOT NULL,
  rating TINYINT NOT NULL DEFAULT 3,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (sign_id) REFERENCES zodiac_signs(id) ON DELETE CASCADE,
  FOREIGN KEY (type_id) REFERENCES horoscope_types(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(150) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  birth_date DATE NULL,
  birth_time TIME NULL,
  birth_place VARCHAR(150) NULL,
  role ENUM('user','admin') NOT NULL DEFAULT 'user',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE astrologers (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  photo VARCHAR(100) NOT NULL,
  specialization VARCHAR(100) NOT NULL,
  experience INT NOT NULL,
  price INT NOT NULL,
  rating DECIMAL(2,1) NOT NULL DEFAULT 5.0,
  about TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE natal_charts (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL UNIQUE,
  birth_date DATE NOT NULL,
  birth_time TIME NOT NULL,
  birth_place VARCHAR(150) NOT NULL,
  latitude DECIMAL(8,5) NOT NULL,
  longitude DECIMAL(8,5) NOT NULL,
  timezone VARCHAR(60) NOT NULL,
  sun_sign_id INT NOT NULL,
  moon_sign_id INT NOT NULL,
  ascendant_sign_id INT NOT NULL,
  sun_degree DECIMAL(5,2) NOT NULL,
  moon_degree DECIMAL(5,2) NOT NULL,
  asc_degree DECIMAL(5,2) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (sun_sign_id) REFERENCES zodiac_signs(id),
  FOREIGN KEY (moon_sign_id) REFERENCES zodiac_signs(id),
  FOREIGN KEY (ascendant_sign_id) REFERENCES zodiac_signs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE consultations (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  astrologer_id INT NOT NULL,
  consult_date DATE NOT NULL,
  consult_time TIME NOT NULL,
  topic VARCHAR(200) NOT NULL,
  format ENUM('Онлайн','Чат') NOT NULL DEFAULT 'Онлайн',
  status ENUM('Новая','Подтверждена','Завершена','Отменена') NOT NULL DEFAULT 'Новая',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (astrologer_id) REFERENCES astrologers(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE reviews (
  id INT AUTO_INCREMENT PRIMARY KEY,
  astrologer_id INT NOT NULL,
  user_id INT NOT NULL,
  rating TINYINT NOT NULL,
  text TEXT NOT NULL,
  is_approved TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (astrologer_id) REFERENCES astrologers(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE articles (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  slug VARCHAR(100) NOT NULL UNIQUE,
  category VARCHAR(50) NOT NULL,
  image VARCHAR(100) NOT NULL,
  excerpt VARCHAR(300) NOT NULL,
  content TEXT NOT NULL,
  astrologer_id INT NULL,
  published_at DATE NOT NULL,
  views INT NOT NULL DEFAULT 0,
  FOREIGN KEY (astrologer_id) REFERENCES astrologers(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

